#!/usr/bin/env bash
set -Eeuo pipefail

TARGET=''

for ARG in "$@"; do
    case "$ARG" in
        --target=erp)
            TARGET='erp'
            ;;
        --target=storefront)
            TARGET='storefront'
            ;;
        *)
            printf 'ERROR: Unknown argument: %s\n' "$ARG" >&2
            exit 1
            ;;
    esac
done

test -n "$TARGET" || {
    printf '%s\n' \
      'Usage: bash <patch>.sh --target=erp|--target=storefront' \
      >&2
    exit 1
}

test -f artisan || {
    printf '%s\n' \
      'ERROR: Run this patch from the intended Laravel project root.' \
      >&2
    exit 1
}

PATCH_NAME="linxen_commerce_customer_session_cart_foundation_v1_${TARGET}"
BACKUP_ROOT="storage/app/ai_patch_backups/${PATCH_NAME}_$(date +%Y%m%d_%H%M%S)"
MANIFEST="${BACKUP_ROOT}/manifest.tsv"
PATCH_WRITTEN=0

backup_file() {
    FILE="$1"

    mkdir -p "$BACKUP_ROOT/$(dirname "$FILE")"

    if [ -e "$FILE" ]; then
        cp -p "$FILE" "$BACKUP_ROOT/$FILE"
        printf 'existing\t%s\n' "$FILE" >> "$MANIFEST"
    else
        printf 'new\t%s\n' "$FILE" >> "$MANIFEST"
    fi
}

rollback() {
    STATUS=$?

    if [ "$PATCH_WRITTEN" -eq 1 ] && [ -f "$MANIFEST" ]; then
        printf 'Rollback target=%s\n' "$TARGET" >&2

        while IFS=$'\t' read -r KIND FILE; do
            case "$KIND" in
                existing)
                    if [ -f "$BACKUP_ROOT/$FILE" ]; then
                        mkdir -p "$(dirname "$FILE")"
                        cp -p "$BACKUP_ROOT/$FILE" "$FILE"
                    fi
                    ;;
                new)
                    rm -f "$FILE"
                    ;;
            esac
        done < "$MANIFEST"
    fi

    exit "$STATUS"
}

trap rollback ERR

decode_to_file() {
    FILE="$1"
    TMP_FILE="$(mktemp "${TMPDIR:-/tmp}/commerce_bundle.XXXXXX")"

    mkdir -p "$(dirname "$FILE")"

    if printf 'Zg==' | base64 --decode >/dev/null 2>&1; then
        base64 --decode > "$TMP_FILE"
    else
        base64 -D > "$TMP_FILE"
    fi

    mv "$TMP_FILE" "$FILE"
    chmod 0644 "$FILE"
}

artisan_safe() {
    if [ "$(id -u)" -eq 0 ] \
        && command -v sudo >/dev/null 2>&1 \
        && id www-data >/dev/null 2>&1
    then
        sudo -u www-data env \
          HOME="$(pwd)" \
          CACHE_STORE=file \
          SESSION_DRIVER=file \
          php artisan "$@"
    else
        env \
          CACHE_STORE=file \
          SESSION_DRIVER=file \
          php artisan "$@"
    fi
}

if [ "$TARGET" = 'erp' ]; then
    REQUIRED=(
        'app/Services/Commerce/CommerceSellableSkuResolver.php'
        'app/Services/Commerce/CommerceCatalogProjectionService.php'
        'app/Services/Commerce/StorefrontScopeResolver.php'
        'app/Http/Middleware/Commerce/CommerceApiExceptionBoundary.php'
        'app/Http/Middleware/Commerce/ResolveCommerceSiteContext.php'
        'app/Support/Commerce/CommerceApiResponse.php'
        'routes/api.php'
    )

    for FILE in "${REQUIRED[@]}"; do
        test -f "$FILE" || {
            printf 'ERROR: Missing ERP dependency: %s\n' "$FILE" >&2
            exit 1
        }
    done

    FILES=(
        'database/migrations/2026_07_16_230537_create_commerce_customer_auth_tables.php'
        'app/Services/Commerce/CommerceCustomerAuthService.php'
        'app/Services/Commerce/CommerceCartValidationService.php'
        'app/Http/Middleware/Commerce/ResolveCommerceCustomerSession.php'
        'app/Http/Controllers/Api/Commerce/V2/CommerceCustomerController.php'
        'app/Http/Controllers/Api/Commerce/V2/CommerceCartController.php'
        'app/Console/Commands/Commerce/CreateCustomerMagicLinkCommand.php'
        'app/Console/Commands/Commerce/AuditCustomerCartFoundationCommand.php'
        'routes/api.php'
    )

    for FILE in "${FILES[@]}"; do
        backup_file "$FILE"
    done

    PATCH_WRITTEN=1

