    export CUSTOMER_CART_ROUTES='routes/api.php'
    export CUSTOMER_CART_ROUTE_BLOCK_FILE="$ROUTE_BLOCK_TMP"

    php <<'PHP'
<?php

$path = getenv('CUSTOMER_CART_ROUTES');
$blockPath = getenv('CUSTOMER_CART_ROUTE_BLOCK_FILE');
$source = file_get_contents($path);
$block = file_get_contents($blockPath);

$start = '/* AI_PATCH_COMMERCE_CUSTOMER_SESSION_CART_FOUNDATION_V1_START */';
$end = '/* AI_PATCH_COMMERCE_CUSTOMER_SESSION_CART_FOUNDATION_V1_END */';

if (! is_string($source) || ! is_string($block)) {
    fwrite(STDERR, "ERROR: Cannot read route source/block.\n");
    exit(1);
}

$startCount = substr_count($source, $start);
$endCount = substr_count($source, $end);

if ($startCount !== $endCount || $startCount > 1) {
    fwrite(STDERR, "ERROR: Commerce customer/cart route marker imbalance.\n");
    exit(1);
}

if ($startCount === 1) {
    $pattern = '/'
        . preg_quote($start, '/')
        . '.*?'
        . preg_quote($end, '/')
        . '/s';

    $patched = preg_replace(
        $pattern,
        trim($block),
        $source,
        1,
        $count
    );

    if (! is_string($patched) || $count !== 1) {
        fwrite(STDERR, "ERROR: Cannot rebuild route block.\n");
        exit(1);
    }
} else {
    $patched = rtrim($source) . "\n\n" . trim($block) . "\n";
}

$written = file_put_contents($path, $patched);

if ($written === false || $written !== strlen($patched)) {
    fwrite(STDERR, "ERROR: Cannot write routes/api.php.\n");
    exit(1);
}
PHP

