    'api/commerce/v2/sites/{site}/customer/auth/exchange',
    'api/commerce/v2/sites/{site}/customer/account',
    'api/commerce/v2/sites/{site}/customer/auth/session',
];

$found = [];

foreach ($app['router']->getRoutes() as $route) {
    if (in_array($route->uri(), $expected, true)) {
        $found[$route->uri()] = $route->getActionName();
    }
}

$missing = array_values(
    array_diff($expected, array_keys($found))
);

if ($missing !== []) {
    fwrite(
        STDERR,
        'Missing routes: ' . implode(', ', $missing) . PHP_EOL
    );
    exit(1);
}

