SF_B64_13

    LINT_FILES=(
        'app/Services/CommerceV2/ErpCommerceClient.php'
        'app/Services/CommerceV2/SessionCartService.php'
        'app/Services/CommerceV2/CustomerSessionService.php'
        'app/Http/Controllers/CommerceV2/CartController.php'
        'app/Http/Controllers/CommerceV2/AccountController.php'
        'app/Console/Commands/CommerceV2SmokeCommand.php'
        'routes/commerce_v2.php'
    )

    for FILE in "${LINT_FILES[@]}"; do
        php -l "$FILE"
    done

    grep -Fq \
      'data-lxv2-cart-form' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq \
      'commerce.v2.cart.index' \
      resources/views/commerce_v2/layouts/app.blade.php

    grep -Fq \
      'sellable_sku_id' \
      public/commerce-v2/commerce.js

    trap - ERR

    if ! artisan_safe optimize:clear; then
        printf '%s\n' \
          'WARNING: optimize:clear failed after mandatory source checks.' \
          >&2
    fi

    if ! artisan_safe view:cache; then
        printf '%s\n' \
          'WARNING: view:cache failed; run it on production after deploy.' \
          >&2
    fi

    artisan_safe view:clear >/dev/null 2>&1 || true

    if php <<'PHP'
<?php

require getcwd() . '/vendor/autoload.php';

$app = require getcwd() . '/bootstrap/app.php';
$app->make(
    Illuminate\Contracts\Console\Kernel::class
)->bootstrap();

$expected = [
    'v2/cart',
    'v2/cart/items',
    'v2/account',
    'v2/account/login/{ticket}',
];

$found = [];

foreach ($app['router']->getRoutes() as $route) {
    if (in_array($route->uri(), $expected, true)) {
        $found[$route->uri()] = $route->getActionName();
    }
}

$missing = array_values(
    array_diff($expected, array_keys($found))
);

if ($missing !== []) {
    fwrite(
        STDERR,
        'Missing Storefront routes: '
            . implode(', ', $missing)
            . PHP_EOL
    );
    exit(1);
}

echo "STOREFRONT_TARGETED_ROUTE_DISCOVERY=PASS\n";
PHP
    then
        :
    else
        printf '%s\n' \
          'WARNING: Storefront targeted route discovery failed; source remains because PHP/Blade markers passed.' \
          >&2
    fi

    printf '%s\n' 'CUSTOMER_CART_STOREFRONT_SOURCE_PATCH=PASS'
    printf '%s\n' 'SESSION_CART=ENABLED'
    printf '%s\n' 'ERP_REVALIDATION_ON_ADD_UPDATE_READ=ENABLED'
    printf '%s\n' 'CUSTOMER_TOKEN_BROWSER_EXPOSURE=NO'
    printf '%s\n' 'MAGIC_LINK_EXCHANGE=ENABLED'
    printf '%s\n' 'ADDRESS_MODE=READ_ONLY_EXISTING_ADDRESSES'
    printf '%s\n' 'CHECKOUT_ORDER=NOT_INCLUDED'
    printf '%s\n' 'DB_MUTATION=NONE'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi
